// Querying causally related entities from different database partitions
async fn read_concluding_dialogue(client: &DbClient) {
    // Partition 1 contains the question
    let question = client.read_partition("p1", "q_101").await.unwrap(); // Lagging

    // Partition 2 contains the answer
    let answer = client.read_partition("p2", "a_101").await.unwrap(); // Up-to-date
    // BUG: If partition 1 is lagging behind partition 2, we might observe 
    // the answer but find the question does not exist yet!
}
